// Exact inner-neck components of the calibrated short-sleeve Front panel.
// Generated by diagnostics/build-neck-mask.py. The closed scan surface is
// neutral fabric, never a printable continuation of the front image.
export const TSHIRT_NECK_FRONT_VERTICES=541461;
export const TSHIRT_NECK_INTERIOR_FACES=14456;
const bytes=Uint8Array.from(atob(''),c=>c.charCodeAt(0));
export const isTshirtNeckInteriorFace=face=>face>=0&&face<TSHIRT_NECK_FRONT_VERTICES/3&&Boolean(bytes[face>>3]&(1<<(face&7)));
export function createTshirtNeckInterior(geometry,THREE,color='#FFFFFF'){
 const position=geometry.getAttribute('position');
 if(position.count!==TSHIRT_NECK_FRONT_VERTICES)throw new Error('Short-sleeve neck interior mask does not match this mesh');
 const outside=[],inside=[];
 for(let face=0;face<position.count/3;face++){
  const target=isTshirtNeckInteriorFace(face)?inside:outside;
  target.push(face*3,face*3+1,face*3+2);
 }
 // Keep the complete attribute arrays and their ordering. Surface calibration
 // and neckline/hem anchors depend on them; only draw indices are separated.
 geometry.setIndex(outside);
 const inner=new THREE.BufferGeometry();inner.setAttribute('position',position);inner.setAttribute('normal',geometry.getAttribute('normal'));inner.setIndex(inside);
 const material=new THREE.MeshStandardMaterial({color,roughness:1,metalness:0,side:THREE.DoubleSide});
 const mesh=new THREE.Mesh(inner,material);mesh.name='MQD_Tshirt_Neck_Interior';mesh.userData.neutralNeckInterior=true;
 return mesh;
}
